function playMovie(){if(MEDIA.awakeningMovie){modal('神格覚醒',`<video controls autoplay playsinline style="width:100%" src="${MEDIA.awakeningMovie}"></video>`);}else cinema('warp','再誕の神格','CSS代替演出 / 専用MP4は未提供',null,10000);}
document.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(!el||el.disabled)return;try{Promise.resolve(handle(el.dataset.action,el.dataset.id)).catch(e=>toast(e.message));}catch(e){toast(e.message);}});
// Decode runtime art once; failed images use the existing local substitute without a retry loop.
for(const src of new Set([ART,FINALE_ART,MEDIA.keyArt,...Object.values(PORTRAITS),...Object.values(ENEMIES),...Object.values(RAID_ART),...Object.values(SCENES),...Object.values(MEDIA.fallenSkills)])){const preload=new Image();preload.src=src;preload.decode?.().catch(()=>{});}
document.addEventListener('error',event=>{const img=event.target;if(img instanceof HTMLImageElement&&!img.dataset.fallback){img.dataset.fallback='1';img.src=ART;}},true);
render();

document.addEventListener('change',e=>{if(e.target.matches('[data-action=mirrorRelic]'))handle('mirrorRelic','').catch(err=>toast(err.message));});

async function resolveDivinityCombat(id){
 const b=battle;if(!b||b.result||combatRecovering)return;const reason=available(b,id);if(reason)throw Error(reason);
 combatRecovering=true;clearTimeout(combatReleaseTimer);syncCombatBusy();const controller=new AbortController(),events=[],before=combatFrame(b),visual=divinityVisualProfile(id,b);
 try{
  observeCombat(b,event=>events.push(event),()=>{if(divTrial(b))actDivinityTrial(b,id);else if(b.main20)actMainBattle(b,id);else if(b.trial?.kind==='mirror')actMirrorTrial(b,id);else if(b.trial?.kind==='guard-break')actGuardBreakTrial(b,id);else if(b.trial)actThreePhase(b,id);else act(b,id);});
  if(b.trial?.kind==='mirror')persistMirror(b);
  if(b.result)b.reward=divTrial(b)?settleDivinityTrial(current(),b):b.main20?settleMainBattle(current(),b):settle(current(),b);
  persist();
  const moment=b.events.find(x=>x.type==='authorityAwakening'||x.type==='apotheosis');
  if(moment){const skill=Object.entries(DIV_SKILLS).find(([key,row])=>row.power===moment.power)?.[0];const at=divinityCommands(b).findIndex(([key])=>key===skill);if(at>=0)divCommandPage=Math.floor(at/divinityPageSize(window.visualViewport?.height||window.innerHeight));}
  if(moment?.type==='authorityAwakening')events.push({kind:'authorityAwakening',power:moment.power,frame:combatFrame(b)});
  try{
   await combatVfxReady;showDivinityCombatFrame(before);
   const presentation=playCombatPresentation({arena:$('.div-arena'),events,action:visual.action,authority:visual.authority||b.powers[0],before,onFrame:showDivinityCombatFrame,onSound:tone,reduced:matchMedia('(prefers-reduced-motion: reduce)').matches,signal:controller.signal,divinity:visual});await presentation.done;
  }catch(error){console.error('Divinity combat presentation failed',error);toast('戦闘表示を復帰しました：'+error.message);}
  render();tone(b.lastDamage>0?'hit':'ultimate');
  if(moment)await playDivinityMoment(moment.type==='apotheosis'?'真・神格解放':DIV_NAMES[moment.power]+' — 封印解除',moment.type==='apotheosis'?DIV_STAGES[5].memory:DIV_TRIALS[moment.power].memory,DIV_ART[moment.type==='apotheosis'?5:Math.max(1,b.build.awakening)]);
 }
 finally{controller.abort();if(b===battle)render();combatRecovering=false;syncCombatBusy();}
}
